BEGIN;
CREATE OR REPLACE FUNCTION operator_qualification_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'operator qualification history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS operator_qualification_scopes (scope_hash text PRIMARY KEY CHECK(scope_hash ~ '^[a-f0-9]{64}$'),operator_test_id text NOT NULL,tenant_fingerprint text NOT NULL,scope_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('local','test')),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(operator_test_id,tenant_fingerprint,scope_id,environment));
CREATE TABLE IF NOT EXISTS operator_role_versions (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),role_hash text PRIMARY KEY CHECK(role_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_training_module_versions (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),module_hash text PRIMARY KEY CHECK(module_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_training_completion_receipts (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_drill_scenario_versions (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),scenario_hash text PRIMARY KEY CHECK(scenario_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_drill_rubrics (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),rubric_hash text PRIMARY KEY CHECK(rubric_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_drill_attempts (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),attempt_hash text PRIMARY KEY CHECK(attempt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_drill_action_receipts (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),action_hash text PRIMARY KEY CHECK(action_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_drill_oracle_receipts (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),oracle_hash text PRIMARY KEY CHECK(oracle_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_reviewer_calibrations (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),calibration_hash text PRIMARY KEY CHECK(calibration_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_independent_review_attestations (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),review_hash text PRIMARY KEY CHECK(review_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_decisions (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),decision_hash text PRIMARY KEY CHECK(decision_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_grants (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),grant_hash text PRIMARY KEY CHECK(grant_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_revocations (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),revocation_hash text PRIMARY KEY CHECK(revocation_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_consumption_receipts (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_transitions (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),transition_hash text PRIMARY KEY CHECK(transition_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_conflicts (scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),conflict_hash text PRIMARY KEY CHECK(conflict_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_qualification_request_claims (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS operator_qualification_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id),scope_hash text NOT NULL REFERENCES operator_qualification_scopes(scope_hash),decision_hash text NOT NULL REFERENCES operator_qualification_decisions(decision_hash),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS operator_qualification_grants_fold_idx ON operator_qualification_grants(scope_hash,(payload->>'principal_hash'),(payload->>'role_hash'),(payload->>'expires_at'));
CREATE UNIQUE INDEX IF NOT EXISTS operator_drill_attempt_nonce_idx ON operator_drill_attempts(scope_hash,(payload->>'nonce'));
CREATE UNIQUE INDEX IF NOT EXISTS operator_review_exact_idx ON operator_independent_review_attestations(scope_hash,(payload->>'reviewer_principal_hash'),(payload->>'attempt_hash'),(payload->>'rubric_hash'));
CREATE UNIQUE INDEX IF NOT EXISTS operator_revocation_identity_idx ON operator_qualification_revocations(scope_hash,(payload->>'grant_hash'),(payload->>'reason_code'));
CREATE INDEX IF NOT EXISTS operator_qualification_consumers_idx ON operator_qualification_consumption_receipts(scope_hash,(payload->>'consumer_feature'));
CREATE OR REPLACE FUNCTION operator_qualification_bundle_scope_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM operator_qualification_decisions d WHERE d.decision_hash=NEW.decision_hash AND d.scope_hash=NEW.scope_hash) THEN RAISE EXCEPTION 'operator qualification cross-scope bundle rejected'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS operator_qualification_bundle_scope_guard ON operator_qualification_test_center_bundles;
CREATE TRIGGER operator_qualification_bundle_scope_guard BEFORE INSERT ON operator_qualification_test_center_bundles FOR EACH ROW EXECUTE FUNCTION operator_qualification_bundle_scope_guard();
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['operator_qualification_scopes','operator_role_versions','operator_training_module_versions','operator_training_completion_receipts','operator_drill_scenario_versions','operator_drill_rubrics','operator_drill_attempts','operator_drill_action_receipts','operator_drill_oracle_receipts','operator_reviewer_calibrations','operator_independent_review_attestations','operator_qualification_decisions','operator_qualification_grants','operator_qualification_revocations','operator_qualification_consumption_receipts','operator_qualification_transitions','operator_qualification_conflicts','operator_qualification_request_claims','operator_qualification_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I',item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION operator_qualification_reject_mutation()',item,item); END LOOP; END $$;
COMMIT;
